#!/bin/bash
# apply_dracarys_fixes.sh
#
# Applies the security, correctness, and portfolio-risk fixes discussed
# in review to a local checkout of the Dracarys FX Pro project.
#
# Run from the ROOT of your project directory (the folder containing
# frontend/, backend/, api/, etc.):
#
#   chmod +x apply_dracarys_fixes.sh
#   ./apply_dracarys_fixes.sh
#
# This OVERWRITES the files listed below with their fixed versions.
# It makes a timestamped backup of each file it touches first, under
# .dracarys-fix-backup-<timestamp>/, so you can diff or roll back.
#
# New files created: api/trade.js, frontend/scripts/scheduler/portfolioRisk.js
#
set -euo pipefail

if [ ! -d "frontend" ] || [ ! -d "backend" ]; then
    echo "Error: run this from the project root (expected frontend/ and backend/ here)."
    exit 1
fi

BACKUP_DIR=".dracarys-fix-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$BACKUP_DIR"
echo "Backing up existing files to $BACKUP_DIR/ ..."

if [ -f "backend/services/server.js" ]; then
    mkdir -p "$BACKUP_DIR/backend/services"
    cp "backend/services/server.js" "$BACKUP_DIR/backend/services/server.js"
fi
if [ -f "api/trade.js" ]; then
    mkdir -p "$BACKUP_DIR/api"
    cp "api/trade.js" "$BACKUP_DIR/api/trade.js"
fi
if [ -f "frontend/src/js/core/app.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/src/js/core"
    cp "frontend/src/js/core/app.js" "$BACKUP_DIR/frontend/src/js/core/app.js"
fi
if [ -f "frontend/src/js/indicators/indicators.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/src/js/indicators"
    cp "frontend/src/js/indicators/indicators.js" "$BACKUP_DIR/frontend/src/js/indicators/indicators.js"
fi
if [ -f "frontend/scripts/scheduler/virtualTrades.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/scripts/scheduler"
    cp "frontend/scripts/scheduler/virtualTrades.js" "$BACKUP_DIR/frontend/scripts/scheduler/virtualTrades.js"
fi
if [ -f "frontend/scripts/scheduler/runScheduler.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/scripts/scheduler"
    cp "frontend/scripts/scheduler/runScheduler.js" "$BACKUP_DIR/frontend/scripts/scheduler/runScheduler.js"
fi
if [ -f "frontend/scripts/scheduler/db.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/scripts/scheduler"
    cp "frontend/scripts/scheduler/db.js" "$BACKUP_DIR/frontend/scripts/scheduler/db.js"
fi
if [ -f "frontend/scripts/scheduler/config.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/scripts/scheduler"
    cp "frontend/scripts/scheduler/config.js" "$BACKUP_DIR/frontend/scripts/scheduler/config.js"
fi
if [ -f "frontend/scripts/scheduler/candles.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/scripts/scheduler"
    cp "frontend/scripts/scheduler/candles.js" "$BACKUP_DIR/frontend/scripts/scheduler/candles.js"
fi
if [ -f "frontend/src/js/analysis/backtestEngine.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/src/js/analysis"
    cp "frontend/src/js/analysis/backtestEngine.js" "$BACKUP_DIR/frontend/src/js/analysis/backtestEngine.js"
fi
if [ -f "frontend/scripts/scheduler/portfolioRisk.js" ]; then
    mkdir -p "$BACKUP_DIR/frontend/scripts/scheduler"
    cp "frontend/scripts/scheduler/portfolioRisk.js" "$BACKUP_DIR/frontend/scripts/scheduler/portfolioRisk.js"
fi
if [ -f ".gitignore" ]; then
    cp ".gitignore" "$BACKUP_DIR/.gitignore"
fi
if [ -f "zip-project.sh" ]; then
    cp "zip-project.sh" "$BACKUP_DIR/zip-project.sh"
fi

echo ""
echo "Writing fixed files..."

echo "  -> backend/services/server.js"
mkdir -p "backend/services"
base64 -d > "backend/services/server.js" << 'B64EOF_0'
