echo ""
echo "Removing stray .bak files that may contain leaked secrets/old code..."
find . -name "*.bak" -not -path "./node_modules/*" -not -path "./frontend/node_modules/*" -not -path "./backend/node_modules/*" -print -delete || true

echo ""
echo "Done."
echo ""
echo "IMPORTANT — manual steps still required:"
echo "  1. Rotate your TwelveData API key, Discord webhook, and reports password"
echo "     (these were previously exposed in frontend/.env inside distributed zips)."
echo "  2. Set TRADE_API_KEY in your backend environment (.env) — the /trade"
echo "     endpoint now refuses all requests until this is set."
echo "  3. Set ALLOWED_ORIGINS in the backend environment to your deployed"
echo "     frontend origin(s), comma-separated, e.g.:"
echo "       ALLOWED_ORIGINS=https://your-frontend.vercel.app"
echo "  4. On Vercel, set TRADE_BACKEND_URL and TRADE_API_KEY as environment"
echo "     variables for the new api/trade.js proxy function."
echo "  5. Review frontend/scripts/scheduler/config.js — maxHoldCandles,"
echo "     ambiguousFillRule, and portfolioRiskLimits are now tunable there."
echo "  6. Run npm install in backend/ and frontend/ if package.json changed"
echo "     (it did not in this patch, so this is likely a no-op)."
echo ""
echo "A backup of every file this script touched is in: $BACKUP_DIR/"
